# --- Growth explorer: published year-on-year growth, any activity -----------

mod_growth_ui <- function(id) {
  ns <- NS(id)
  layout_sidebar(
    sidebar = sidebar(
      width = 320, open = "open",
      uiOutput(ns("items_ui")),
      uiOutput(ns("hl_ui")),
      uiOutput(ns("years_ui")),
      radioButtons(ns("layout"), "Layout",
                   c("One chart" = "single", "Small multiples" = "facet"), inline = TRUE),
      checkboxInput(ns("ma"), "Smooth with a four-quarter average", FALSE),
      note("Year-on-year growth at constant 2013 prices, as published by GSS.")
    ),
    card(
      full_screen = TRUE,
      card_header("Year-on-year growth"),
      card_body(girafeOutput(ns("plot"), height = "640px")),
      card_footer(downloadButton(ns("dl"), "Download this selection (CSV)"))
    )
  )
}

mod_growth_server <- function(id, dat) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns

    output$items_ui <- renderUI({
      d <- dat()
      selectInput(ns("items"), "Activities", multiple = TRUE,
                  choices = grouped_choices(d$sector_map),
                  selected = intersect(c("GDP", "Non-oil GDP", "ICT"), d$sector_map$item))
    })

    output$hl_ui <- renderUI({
      req(input$items)
      selectInput(ns("hl"), "Highlight", choices = input$items, selected = input$items[1])
    })

    output$years_ui <- renderUI({
      d <- dat()
      year_slider(ns("years"), d$years)
    })

    plot_data <- reactive({
      d <- dat(); req(input$items, input$years)
      out <- d$yoy |>
        dplyr::filter(.data$item %in% input$items) |>
        dplyr::arrange(.data$item, .data$t)
      if (isTRUE(input$ma)) {
        out <- out |>
          dplyr::group_by(.data$item) |>
          dplyr::mutate(value = (.data$value + dplyr::lag(.data$value) +
                                   dplyr::lag(.data$value, 2) + dplyr::lag(.data$value, 3)) / 4) |>
          dplyr::ungroup() |>
          dplyr::filter(!is.na(.data$value))
      }
      out |> dplyr::filter(.data$year >= input$years[1], .data$year <= input$years[2])
    })

    output$plot <- renderGirafe({
      df <- plot_data()
      validate(need(nrow(df) > 0, "No data for that selection."))
      last_p <- df$period[which.max(df$t)]
      sub <- if (isTRUE(input$ma)) {
        paste0("Four-quarter average of year-on-year growth, to ", last_p)
      } else {
        paste0("Year-on-year growth in real value added, to ", last_p)
      }
      gf(line_chart(df, highlight = input$hl,
                    title = "How Fast Each Part of the Economy Is Growing",
                    subtitle = sub, unit = "%", zero_line = TRUE,
                    facet = identical(input$layout, "facet")),
         height = 6.4)
    })

    output$dl <- downloadHandler(
      filename = \() paste0("ghana_gdp_growth_", Sys.Date(), ".csv"),
      content  = \(f) readr::write_csv(plot_data(), f)
    )
  })
}

# --- Momentum: seasonally adjusted quarter-on-quarter change ----------------

mod_momentum_ui <- function(id) {
  ns <- NS(id)
  layout_sidebar(
    sidebar = sidebar(
      width = 320, open = "open",
      uiOutput(ns("items_ui")),
      uiOutput(ns("hl_ui")),
      uiOutput(ns("years_ui")),
      checkboxInput(ns("annualise"), "Show at an annual rate", FALSE),
      radioButtons(ns("layout"), "Layout",
                   c("One chart" = "single", "Small multiples" = "facet"), inline = TRUE),
      note("Quarter-on-quarter change with the usual seasonal pattern removed. This is the ",
           "measure that turns first, well before the year-on-year rate reacts.")
    ),
    card(
      full_screen = TRUE,
      card_header("Seasonally adjusted momentum"),
      card_body(girafeOutput(ns("plot"), height = "620px")),
      card_footer(downloadButton(ns("dl"), "Download this selection (CSV)"))
    )
  )
}

mod_momentum_server <- function(id, dat) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns

    output$items_ui <- renderUI({
      d <- dat()
      validate(need(!is.null(d$sa), "This workbook has no seasonally adjusted table."))
      ch <- sort(unique(d$sa$item))
      selectInput(ns("items"), "Series", choices = ch, multiple = TRUE,
                  selected = intersect(c("GDP"), ch))
    })

    output$hl_ui <- renderUI({
      req(input$items)
      selectInput(ns("hl"), "Highlight", choices = input$items, selected = input$items[1])
    })

    output$years_ui <- renderUI({
      d <- dat(); req(d$sa); year_slider(ns("years"), sort(unique(d$sa$year)))
    })

    plot_data <- reactive({
      d <- dat(); req(d$sa, input$items, input$years)
      out <- d$sa |>
        dplyr::filter(.data$item %in% input$items,
                      .data$year >= input$years[1], .data$year <= input$years[2])
      if (isTRUE(input$annualise)) {
        out <- dplyr::mutate(out, value = ((1 + .data$value / 100)^4 - 1) * 100)
      }
      out |> dplyr::arrange(.data$item, .data$t)
    })

    output$plot <- renderGirafe({
      d <- dat()
      validate(need(!is.null(d$sa), "This workbook has no seasonally adjusted table."))
      df <- plot_data()
      validate(need(nrow(df) > 0, "No data for that selection."))
      gf(line_chart(df, highlight = input$hl,
                    title = "Momentum, Quarter on Quarter",
                    subtitle = paste0("Seasonally adjusted change on the previous quarter",
                                      if (isTRUE(input$annualise)) ", at an annual rate" else ""),
                    unit = "%", zero_line = TRUE,
                    facet = identical(input$layout, "facet")),
         height = 6.2)
    })

    output$dl <- downloadHandler(
      filename = \() paste0("ghana_gdp_momentum_", Sys.Date(), ".csv"),
      content  = \(f) readr::write_csv(plot_data(), f)
    )
  })
}

# --- Structure: share of value added, by activity, over time ----------------

mod_structure_ui <- function(id) {
  ns <- NS(id)
  layout_sidebar(
    sidebar = sidebar(
      width = 320, open = "open",
      uiOutput(ns("items_ui")),
      uiOutput(ns("hl_ui")),
      uiOutput(ns("years_ui")),
      radioButtons(ns("freq"), "Frequency", c("Annual" = "a", "Quarterly" = "q"), inline = TRUE),
      radioButtons(ns("disp"), "Display", c("Lines" = "line", "Stacked area" = "area"),
                   inline = TRUE),
      note("Share of gross value added at current prices. Movements reflect both real activity ",
           "and relative prices. The last year is partial if the bulletin stops mid-year.")
    ),
    card(
      full_screen = TRUE,
      card_header("Share of value added"),
      card_body(girafeOutput(ns("plot"), height = "620px")),
      card_footer(downloadButton(ns("dl"), "Download this selection (CSV)"))
    )
  )
}

mod_structure_server <- function(id, dat) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns

    item_map <- reactive({
      d <- dat()
      d$shares |>
        dplyr::distinct(.data$item) |>
        dplyr::left_join(dplyr::mutate(d$sector_map, sector = as.character(.data$sector)),
                         by = "item") |>
        dplyr::mutate(sector = tidyr::replace_na(.data$sector, "Other"))
    })

    output$items_ui <- renderUI({
      m <- item_map()
      selectInput(ns("items"), "Activities", multiple = TRUE,
                  choices = grouped_choices(m),
                  selected = intersect(c("Manufacturing", "Wholesale & retail trade"), m$item))
    })

    output$hl_ui <- renderUI({
      req(input$items)
      selectInput(ns("hl"), "Highlight", choices = input$items, selected = input$items[1])
    })

    output$years_ui <- renderUI({
      d <- dat(); year_slider(ns("years"), d$years, value = range(d$years))
    })

    plot_data <- reactive({
      d <- dat(); req(input$items, input$years, input$freq)
      base <- if (identical(input$freq, "a")) {
        annual_shares(d$shares, d$gva)
      } else {
        d$shares
      }
      base |>
        dplyr::filter(.data$item %in% input$items,
                      .data$year >= input$years[1], .data$year <= input$years[2]) |>
        dplyr::arrange(.data$item, .data$t)
    })

    output$plot <- renderGirafe({
      df <- plot_data()
      validate(need(nrow(df) > 0, "No data for that selection."))
      sub <- paste0("Share of gross value added at current prices, ",
                    if (identical(input$freq, "a")) "annual" else "quarterly")

      p <- if (identical(input$disp, "area")) {
        stack_chart(df, area = TRUE, unit = "%",
                    title = "How the Shape of the Economy Has Changed", subtitle = sub)
      } else {
        line_chart(df, highlight = input$hl, unit = "%",
                   title = "How the Shape of the Economy Has Changed", subtitle = sub)
      }
      gf(p, height = 6.2)
    })

    output$dl <- downloadHandler(
      filename = \() paste0("ghana_gdp_shares_", Sys.Date(), ".csv"),
      content  = \(f) readr::write_csv(plot_data(), f)
    )
  })
}
